regions_path = ROOT/'assets/regions.json'
regions = json.loads(regions_path.read_text()) if regions_path.exists() else {}
images = {}
for s in slides:
    name = s['image']
    path = ROOT/'assets'/f'{name}.jpg'
    if path.exists():
        images[name] = 'data:image/jpeg;base64,' + base64.b64encode(path.read_bytes()).decode()
    else:
        raise FileNotFoundError(path)

